contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _log) public payable {
        // On a fresh C, intitalized is false, so SetLogFile must succeed.
        bool firstReverted;
        try c.SetLogFile(_log) { firstReverted = false; } catch { firstReverted = true; }

        // Record whether the first call succeeded.
        bool succeededFirst = !firstReverted;

        // Make a second call with the same argument; after a successful first call,
        // intitalized is true, so the second call MUST revert.
        bool secondReverted;
        try c.SetLogFile(_log) { secondReverted = false; } catch { secondReverted = true; }

        // General rule: first call succeeds, and any call after initialization reverts.
        assert(succeededFirst && secondReverted);
    }
